WITH metrics AS (SELECT *, MAX(pressure) OVER w_grp AS running_max_pressure, COUNT(pressure) OVER w_grp AS running_count_pressure, SUM(pressure) OVER w_grp AS running_sum_pressure, ROW_NUMBER() OVER (ORDER BY status_bits, id) AS seq_no FROM device_readings WINDOW w_grp AS (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, CORR(status_bits, pressure) AS corr_status_bits_pressure, COUNT(DISTINCT device_code) AS distinct_device_codes, MIN(reading_ts) AS started_at, COUNT(*) AS cnt, GROUPING_ID() AS grouping_level FROM metrics GROUP BY ROLLUP (DATE_TRUNC('DAY', reading_ts))
